(()=>{'use strict';
const E=TradeGame,$=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'$'+Math.round(v).toLocaleString('es-MX'),sign=v=>(v>=0?'+':'−')+money(Math.abs(v)),colors={grain:'#f5d579',copper:'#c5adf1',oil:'#ffb26c'};
let s=E.start(),region='factory',quantity=10,paused=true,speed=1,elapsed=0,last=performance.now(),toastTimer,modalWasPaused=true,started=false;
try{const saved=JSON.parse(localStorage.getItem('mv-strategy-v1'));if(valid(saved)){s=saved;started=true;$('start').textContent='Continuar mi empresa →';$('intro').querySelector('h1').textContent='Tus rutas te esperan.';}}catch{}
function valid(x){if(!x||!Number.isInteger(x.month)||x.month<0||x.month>17||!Number.isFinite(x.cash)||Math.abs(x.cash)>1e7)return false;for(const prop of ['raw','made','prices','open'])if(!x[prop]||!Object.keys(E.GOODS).every(k=>prop==='open'?typeof x[prop][k]==='boolean':Number.isFinite(x[prop][k])&&x[prop][k]>=0&&x[prop][k]<1e6))return false;if(![10,20].includes(x.capacity)||!Number.isInteger(x.used)||x.used<0||x.used>x.capacity||!Number.isInteger(x.rep)||x.rep<0||x.rep>5||!Number.isInteger(x.delivered)||x.delivered<0||!Number.isInteger(x.nextId)||!Number.isInteger(x.delayUntil)||typeof x.finished!=='boolean')return false;for(const a of ['contracts','shipments','hedges','history','log'])if(!Array.isArray(x[a])||x[a].length>100)return false;const numeric=(o,keys)=>keys.every(k=>Number.isFinite(o[k])&&Math.abs(o[k])<1e7);if(!x.contracts.every(c=>E.GOODS[c.key]&&numeric(c,['id','qty','reward','deadline'])&&['open','shipping','done','missed'].includes(c.status)))return false;if(!x.shipments.every(t=>E.GOODS[t.key]&&numeric(t,['id','qty','depart','arrival'])&&['buy','sale'].includes(t.type)&&(t.type!=='sale'||x.contracts.some(c=>c.id===t.contract))))return false;if(!x.hedges.every(h=>E.GOODS[h.key]&&['future','call'].includes(h.type)&&numeric(h,['id','qty','strike','last','expiry','margin','premium','pnl'])&&typeof h.closed==='boolean'))return false;if(!x.history.every(h=>Object.keys(E.GOODS).every(k=>Number.isFinite(h[k]))))return false;x.event=E.EVENTS[x.month];return true;}
function save(){try{localStorage.setItem('mv-strategy-v1',JSON.stringify(s));}catch{}}
function toast(text,bad=false){$('toast').textContent=text;$('toast').className='toast'+(bad?' bad':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),3600);}
function act(fn,...args){const err=fn(s,...args);if(err){toast(err,true);return;}save();render();if(fn===E.produce)toast('Producción lista. Envíala desde Pedidos.');else if(fn===E.deliver)toast('Barco enviado. El pago llega con la entrega.');else if(fn===E.buy)toast('Compra en camino. Llegará al avanzar el tiempo.');else if(fn===E.hedge)toast('Contrato abierto. Verás sus movimientos en la mesa de riesgo.');else toast('Decisión aplicada.');}
function advance(){if(s.finished)return;const before=s.cash;E.tick(s);elapsed=0;save();render();if(s.cash>before){const f=document.createElement('div');f.className='floating';f.textContent=sign(s.cash-before);document.querySelector('.mapCard').append(f);setTimeout(()=>f.remove(),1800);}if(s.finished){paused=true;end();}}
function hint(){if(s.finished)return 'Temporada cerrada. Puedes explorar tus resultados o iniciar otra partida.';const ready=s.contracts.find(c=>c.status==='open'&&s.made[c.key]>=c.qty);if(ready)return `⚓ Tienes ${E.GOODS[ready.key].product} listo: envía su pedido para cobrar ${money(ready.reward)}.`;const can=s.contracts.find(c=>c.status==='open'&&s.raw[c.key]>=c.qty&&s.capacity-s.used>=c.qty);if(can)return `🏭 Puedes fabricar ${can.qty} de ${E.GOODS[can.key].product}. Hay insumos disponibles.`;if(s.shipments.length)return '🚢 Hay barcos en ruta. Avanza un mes para que lleguen; las rutas congestionadas tardan dos.';if(s.used===s.capacity)return '🏭 La fábrica terminó su turno. Avanza un mes o amplía su capacidad.';const open=s.contracts.find(c=>c.status==='open');return open?`🧭 Necesitas ${E.GOODS[open.key].name} para el próximo pedido. Selecciona su región.`:'🧭 Prepara inventario, abre rutas o protege costos. Llegan pedidos cada dos meses.';}
function render(){
$('cash').textContent=money(s.cash);$('value').textContent=money(E.value(s));$('collateral').textContent=money(s.hedges.reduce((n,h)=>n+h.margin,0))+' en garantía';$('delivered').textContent=s.delivered+' / 7';$('rival').textContent='Rival: '+s.rival+' / 8 entregas';$('month').textContent=(s.month+1)+' / 18';$('rep').textContent='Reputación: '+('★'.repeat(s.rep))+('☆'.repeat(5-s.rep));$('weather').textContent=s.month<s.delayUntil?'🌊 Viajes: 2 meses':'⛵ Viajes: 1 mes';$('capacity').textContent='Producción: '+s.used+' / '+s.capacity+' este mes';$('eventTitle').textContent=s.event.title;$('eventText').textContent=s.event.text;$('eventIcon').textContent=['🌤️','☀️','🏗️','🔥','🌾','🌊','⚡','🛢️','⛈️','⛵','🏙️','📦','🌡️','🌾','🚧','📈','🌤️','🏁'][s.month];$('hint').textContent=hint();
$('inventory').innerHTML=Object.entries(E.GOODS).map(([k,g])=>`<div class="stock"><b>${g.icon} ${g.name}</b><div>Insumos <strong>${s.raw[k]}</strong></div><div>${g.made} ${g.product} <strong>${s.made[k]}</strong></div></div>`).join('');
$('prices').innerHTML=`<div style="display:flex;justify-content:space-between;gap:8px">${Object.entries(E.GOODS).map(([k,g])=>`<span style="color:${colors[k]};font-size:12px">${g.icon} ${g.name} <b>${money(s.prices[k])}</b></span>`).join('')}</div>`;
const max=Math.max(30,...s.history.flatMap(h=>Object.values(h)));$('chart').innerHTML=`<path d="M10 80H690" stroke="#354960"/>`+Object.keys(E.GOODS).map(k=>`<polyline fill="none" stroke="${colors[k]}" stroke-width="2.5" points="${s.history.map((h,i)=>`${10+i*680/17},${80-h[k]*65/max}`).join(' ')}"/><circle cx="${10+s.month*680/17}" cy="${80-s.prices[k]*65/max}" r="4" fill="${colors[k]}"/>`).join('');
Object.keys(E.GOODS).forEach(k=>$(k+'-label').textContent=money(s.prices[k])+' / unidad'+(s.open[k]?' · Ruta abierta':' · Abrir: $75'));$('factory-label').textContent=s.capacity+' unidades / mes';
document.querySelectorAll('[data-region]').forEach(b=>b.classList.toggle(b.tagName.toLowerCase()==='g'?'active':'active',b.dataset.region===region));renderActions();renderContracts();renderHedges();$('log').innerHTML=s.log.map(l=>`<p class="${l.kind==='good'?'good':l.kind==='bad'?'bad':''}"><time>M${esc(l.month)}</time>${esc(l.text)}</p>`).join('');$('advance').disabled=s.finished;$('pause').disabled=s.finished;drawShips();clock();
}
function qtyButtons(){return `<div class="choices" aria-label="Cantidad de unidades">${[5,10,20].map(n=>`<button data-qty="${n}" class="${n===quantity?'selected':''}">${n} unidades</button>`).join('')}</div>`;}
function renderActions(){let html='';if(region==='factory'){html=`<div class="actionTitle"><h2>🏭 Isla taller</h2><button class="quiet small" data-action="upgrade" ${s.capacity===20||s.cash<160?'disabled':''}>${s.capacity===20?'Ampliada ✓':'Ampliar · $160'}</button></div><div class="subtitle">Transforma insumos en productos. Cada mes puedes fabricar ${s.capacity} unidades en total.</div>${qtyButtons()}`+Object.entries(E.GOODS).map(([k,g])=>`<div class="row"><span>${g.made} <strong>${g.product}</strong><small>Consume ${quantity} ${g.name} + ${money(quantity*g.cost)}</small></span><button data-action="produce" data-key="${k}" ${s.raw[k]<quantity||s.cash<quantity*g.cost||s.used+quantity>s.capacity?'disabled':''}>Fabricar</button></div>`).join('');}
else if(region==='market'){html=`<h2>⚓ Puerto destino</h2><p class="subtitle">Aquí cobras al entregar. Un pedido tiene precio pactado: no cambia cuando sube tu materia prima.</p><div class="nextHint">Envía los productos desde la lista de pedidos. Despachar reserva tu inventario; el barco tarda ${s.month<s.delayUntil?2:1} mes(es).</div><p class="fine">Los pedidos vencidos cuestan $20 y una estrella de reputación. Los nuevos aparecen cada dos meses.</p>`;}
else{const g=E.GOODS[region],k=region;html=`<h2>${g.icon} ${g.name} · ${money(s.prices[k])} / unidad</h2><p class="subtitle">Para producir ${g.product.toLowerCase()}, compra insumos aquí. Llegan en ${s.month<s.delayUntil?2:1} mes(es).</p>`;if(!s.open[k])html+=`<button class="orange" style="width:100%" data-action="unlock" data-key="${k}" ${s.cash<75?'disabled':''}>Abrir ruta comercial · $75</button><p class="fine">Puedes contratar coberturas aunque todavía no hayas abierto la ruta.</p>`;else html+=qtyButtons()+`<button class="orange" style="width:100%" data-action="buy" data-key="${k}" ${s.cash<quantity*s.prices[k]?'disabled':''}>Comprar ${quantity} · ${money(quantity*s.prices[k])}</button>`;
html+=`<div style="border-top:1px solid var(--line);margin-top:16px;padding-top:15px"><h2>Protege tu próxima compra</h2><div class="row"><span>📌 Futuro largo · 10 unidades<small>Referencia ${money(s.prices[k])} · 3 meses · garantía $30</small></span><button class="small" data-action="future" data-key="${k}" ${s.cash<30||s.month+3>17||s.hedges.filter(h=>!h.closed).length>=3?'disabled':''}>Abrir</button></div><div class="row"><span>🛡️ Call · 10 unidades<small>Strike ${money(s.prices[k])} · 3 meses · prima $20</small></span><button class="small" data-action="call" data-key="${k}" ${s.cash<20||s.month+3>17||s.hedges.filter(h=>!h.closed).length>=3?'disabled':''}>Comprar</button></div><p class="fine">El futuro paga si sube y cobra si baja. La call paga al vencer si supera el strike; puede perder toda la prima. Ambos se liquidan en efectivo, sin entregar insumos.</p></div>`;}
$('actions').innerHTML=html;if(s.finished)$('actions').querySelectorAll('button').forEach(b=>b.disabled=true);
}
function renderContracts(){const list=s.contracts.filter(c=>['open','shipping'].includes(c.status));$('orderCount').textContent=list.length+' activos';$('contracts').innerHTML=list.length?list.map(c=>{const g=E.GOODS[c.key],travel=s.month<s.delayUntil?2:1,ready=s.made[c.key]>=c.qty,late=s.month+travel>c.deadline,shipping=c.status==='shipping';return `<div class="contract ${c.deadline-s.month<=2?'urgent':''}"><div class="contractHeader"><strong>${g.made} ${c.qty} ${g.product}</strong><b style="color:var(--mint)">${money(c.reward)}</b></div><p>${shipping?'🚤 En camino · pago al llegar':`Plazo: ${c.deadline-s.month} mes(es) · tienes ${s.made[c.key]} listos`}</p><button class="${ready&&!late&&!shipping?'pulse':'quiet'}" data-deliver="${c.id}" ${!ready||late||shipping||s.finished?'disabled':''}>${shipping?'Barco en ruta':late?'Ya no llega a tiempo':ready?'Enviar pedido →':`Falta producir ${c.qty-s.made[c.key]}`}</button></div>`;}).join(''):'<div class="empty">No hay pedidos pendientes.<br>Prepárate para los siguientes.</div>';}
function renderHedges(){const all=s.hedges.slice().reverse().slice(0,5);$('hedges').innerHTML=all.length?all.map(h=>`<div class="hedge"><strong>${h.type==='future'?'📌 Futuro largo':'🛡️ Call'} · ${E.GOODS[h.key].name}</strong><div><span>${h.qty} unidades · ${money(h.strike)}</span><span>${h.closed?'Cerrado':'Vence M'+(h.expiry+1)}</span></div><div style="margin-top:8px"><span>${h.type==='future'?'Ajustes acumulados':'Resultado realizado'}</span><b class="${h.pnl<0?'loss':'pnl'}">${h.type==='call'&&!h.closed?'Pendiente':sign(h.pnl)}</b></div>${h.type==='call'&&!h.closed?`<p class="fine" style="margin-bottom:0">Si venciera a este precio: ${sign(Math.max(0,s.prices[h.key]-h.strike)*h.qty-h.premium)} netos (prima incluida).</p>`:''}${h.type==='future'&&!h.closed?`<button class="quiet small" data-close="${h.id}">Cerrar y recuperar garantía ${money(h.margin)}</button>`:''}</div>`).join(''):'<div class="empty">No tienes coberturas.<br>Selecciona una materia prima para abrir una.</div>';}
function drawShips(){const ns='http://www.w3.org/2000/svg',group=$('ships');group.replaceChildren();for(const ship of s.shipments){const path=$(ship.type==='buy'?ship.key+'-route':'sale-route');if(!path)continue;const total=ship.arrival-ship.depart;const p=Math.max(0,Math.min(.98,(s.month-ship.depart+elapsed/15000)/total)),point=path.getPointAtLength(path.getTotalLength()*p);const g=document.createElementNS(ns,'g');g.setAttribute('transform',`translate(${point.x},${point.y})`);g.setAttribute('class','shipIcon');const c=document.createElementNS(ns,'circle');c.setAttribute('r','16');c.setAttribute('fill',ship.type==='buy'?colors[ship.key]:'#8be0bd');g.append(c);const text=document.createElementNS(ns,'text');text.setAttribute('text-anchor','middle');text.setAttribute('y','6');text.setAttribute('font-size','20');text.textContent=ship.type==='buy'?'🚢':'🚤';g.append(text);const label=document.createElementNS(ns,'text');label.setAttribute('text-anchor','middle');label.setAttribute('y','-23');label.setAttribute('font-size','11');label.setAttribute('fill','#fff');label.textContent=ship.qty+' '+E.GOODS[ship.key].icon;g.append(label);group.append(g);}}
function clock(){$('pause').textContent=paused?'▶ Reanudar':'Ⅱ Pausar';$('clockLabel').textContent=s.finished?'Temporada cerrada':paused?'Tiempo en pausa':Math.ceil((15000-elapsed)/1000/speed)+' s al próximo mes';$('clockBar').style.width=(elapsed/15000*100)+'%';}
function showModal(html){modalWasPaused=paused;paused=true;$('modalBody').innerHTML=html;$('modal').classList.remove('hidden');clock();$('closeModal').focus();}
function end(){const r=E.result(s);showModal(`<div class="eyebrow">La temporada ha terminado</div><h1>${r.won?'Tus rutas hicieron historia.':'Tu empresa tiene otra oportunidad.'}</h1><p>${r.won?'Cumpliste ambos objetivos y conservaste tu reputación.':s.cash<0?'Te quedaste sin liquidez. Tener inventario o contratos no garantiza efectivo para pagar hoy.':s.rep===0?'Los plazos dañaron tu reputación. Coordina producción y barcos antes de abrir más frentes.':'Revisa qué te faltó: puedes ajustar tu siguiente temporada.'}</p><div class="detailGrid"><div><strong>${s.delivered} / 7</strong><small>Pedidos entregados</small></div><div><strong>${money(r.value)}</strong><small>Valor · objetivo $1,200</small></div></div><h3>Lo que dejaron tus decisiones</h3><p>${s.hedges.length?`Tus coberturas cerradas realizaron ${sign(s.hedges.filter(h=>h.closed).reduce((n,h)=>n+h.pnl,0))}. Ese resultado hay que leerlo junto al costo de comprar tus insumos.`:'Operaste sin coberturas: asumiste los cambios de costo con tu efectivo e inventario.'}</p><p class="fine">Valor incluye inventarios, envíos pendientes y el valor intrínseco aproximado de calls abiertas; no es una cotización para venderlas. La carrera exige 7 entregas; tu rival terminó con ${s.rival}. En este prototipo la misma secuencia de eventos permite probar estrategias distintas.</p><button class="cta" id="playAgain">Probar otra estrategia →</button>`);$('playAgain').onclick=newGame;}
function newGame(){s=E.start();region='factory';quantity=10;paused=true;elapsed=0;started=true;$('modal').classList.add('hidden');$('intro').classList.add('hidden');save();render();toast('Nueva empresa. Empieza por fabricar 10 de pan.');}
function help(risk=false){showModal(risk?`<div class="eyebrow">Tu caja y el riesgo</div><h1>Dos herramientas,<br>dos compromisos.</h1><p><b>Futuro largo:</b> si el trigo sube $4, tu contrato por 10 unidades abona $40. Si baja $4, te cobra $40. El ajuste llega cada mes. Tu compra de trigo sigue al precio del mercado: el ajuste compensa el cambio de costo cuando coinciden cantidad y período.</p><p><b>Call:</b> pagas $20 por el derecho. Al vencer, cobras 10 × lo que el precio supere el strike. Si no lo supera, no cobras; la prima ya se gastó. Conservas el beneficio de comprar insumos más baratos si bajan.</p><p><b>Garantía:</b> $30 del futuro quedan inmovilizados y vuelven al cerrar o vencer. No son la pérdida máxima. Una bajada puede exigir más efectivo.</p><p class="fine">Modelo educativo: tres meses, 10 unidades, call europea con liquidación en efectivo y prima fija. Sin comisiones, interés, riesgo de base, mercado de reventa de opciones ni mantenimiento de margen. Si falta efectivo se cierra un futuro y se libera su garantía. No reproduce contratos de CME ni prepara por sí solo para operar.</p>`:`<div class="eyebrow">Juega a tu ritmo</div><h1>Compra. Transforma.<br>Entrega. Decide.</h1><p>Selecciona una región del mapa. En la <b>fábrica</b> conviertes insumos en productos. En las regiones compras insumos y abres rutas. En <b>pedidos</b> envías productos y cobras cuando llegan.</p><p>La fábrica se renueva cada mes. Los barcos tardan uno; una congestión al despachar alarga su viaje a dos. Los pedidos vencidos cuestan dinero y reputación.</p><p>Reanuda el reloj o usa <b>Avanzar mes</b>. Pausar no cuesta nada. Puedes ampliar la fábrica y contratar futuros o calls en cada región.</p><p>Al cerrar: <b>7 pedidos entregados, empresa de $1,200 y reputación positiva</b>. No necesitas ganarle al rival para cumplir el objetivo.</p><p class="fine">El progreso se guarda en este navegador cuando permite almacenamiento local. Precios ficticios; escenario fijo. Sin cuentas ni IA durante la partida.</p>`);}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-region],[data-action],[data-qty],[data-deliver],[data-close]');if(!b||b.disabled)return;if(b.dataset.region){region=b.dataset.region;render();}else if(b.dataset.qty){quantity=Number(b.dataset.qty);renderActions();}else if(b.dataset.deliver)act(E.deliver,Number(b.dataset.deliver));else if(b.dataset.close)act(E.close,Number(b.dataset.close));else{const k=b.dataset.key;switch(b.dataset.action){case 'produce':act(E.produce,k,quantity);break;case 'buy':act(E.buy,k,quantity);break;case 'unlock':act(E.unlock,k);break;case 'upgrade':act(E.upgrade);break;case 'future':act(E.hedge,k,'future');break;case 'call':act(E.hedge,k,'call');break;}}});
document.querySelectorAll('g[data-region]').forEach(g=>g.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();region=g.dataset.region;render();}}));
$('start').onclick=()=>{started=true;$('intro').classList.add('hidden');render();if(s.finished)end();else toast('Empieza por fabricar pan. Tú decides cuándo avanzar.');};$('pause').onclick=()=>{paused=!paused;clock();};$('advance').onclick=advance;$('speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;$('speed').textContent=speed+'×';clock();};$('help').onclick=()=>help();$('riskHelp').onclick=()=>help(true);$('restart').onclick=()=>{showModal('<div class="eyebrow">Nueva temporada</div><h1>¿Empezar de nuevo?</h1><p>Se sustituirá la partida guardada en este navegador.</p><button class="danger" id="confirmRestart">Sí, abrir una nueva empresa</button>');$('confirmRestart').onclick=newGame;};$('closeModal').onclick=()=>{$('modal').classList.add('hidden');paused=s.finished?true:modalWasPaused;clock();};document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!$('modal').classList.contains('hidden'))$('closeModal').click();});document.addEventListener('visibilitychange',()=>{if(document.hidden){paused=true;save();clock();}});
function frame(now){const dt=Math.min(250,now-last);last=now;if(started&&!paused&&!s.finished&&!document.hidden){elapsed+=dt*speed;if(elapsed>=15000)advance();drawShips();clock();}requestAnimationFrame(frame);}render();requestAnimationFrame(frame);
})();
